# GHD7 LT3 copy (demo_count_20261031/scripts/make_load_tool_lt3.py, from LT2 pool850_ram144_20261031/board/load_tool; identity from the verified package record) - LT2 header follows: GHD6 LT2 copy (scripts/make_load_tool_g6.py) of gold_hud_dualelf_20261030/board/load_tool/load_session_pkg.py; additions: 144 KiB RAM gates.
"""Package-driven board load (generated by scripts/make_load_tool.py from the board-verified load_20261031/attempt2/load_session.py;
the sequence and checks are unchanged, only the package constants come from pkg_env). Usage: python -I -B load_session_pkg.py <package dir> <log dir>
One OpenOCD + one GDB session from load to Resume, no disconnect/reconnect in between.
Launch sequence of apbTest_ti_RAM160_board_manual.launch: gdb client commands, monitor reset init, load, monitor reset halt,
tbreak main, continue. Then, in the same session, the start-up state is checked:
  - main breakpoint address as resolved by GDB ('Temporary breakpoint 1 at ...') == stop pc, inside main (nm -S);
  - instruction word and disassembly at pc equal the ELF (breakpoint removed, image intact);
  - sp == _sp - main frame (first instruction of main 'addi sp,sp,-N': start.S set sp, only main's prologue ran); gp == __global_pointer$;
  - RAM image 0xF9000000..+image length (objcopy of the package ELF) read back after load == objcopy(ELF);
  - pc stable: two GDB reads and two OpenOCD 'reg pc' reads, 2 s apart, all equal; OpenOCD state 'halted'.
Only if all hold: Resume = OpenOCD 'resume' of the current pc issued through the same GDB connection ('monitor resume'); PC is never
written. The session stays up until COM15 shows the start-up banner and answers ASSET BUILD; then GDB disconnects (state must stay
'running'), OpenOCD shuts down, and ASSET BUILD must answer again with no second banner (no reset). On any failed check the CPU is left
halted, tools are closed, nothing is retried. Logs: the log directory given on the command line."""
from pathlib import Path
import argparse, datetime, hashlib, json, re, subprocess, sys, threading, time, traceback
sys.path.insert(0, str(Path(__file__).resolve().parent))
import portable_runtime as s3
import pkg_env
TC = s3.TC
PKGENV = D = EXPECTED = EXPECTED_SHA = IMG_N = BUILD_B = None
R = {'start': datetime.datetime.now().isoformat(timespec='seconds'), 'steps': []}


class OwnedSession:
    """Cleanup only handles created by this process; every branch is best-effort."""
    def __init__(self):
        self.com = self.gdb = self.ocd = self.ocd_log = self.tcl = None
    def cleanup(self):
        errors = []
        def attempt(name, action):
            try: action()
            except Exception as exc: errors.append({'resource': name, 'error': repr(exc)})
        if self.gdb is not None:
            attempt('owned_gdb', self.gdb.close)
        if self.tcl is not None:
            if self.ocd is not None and self.ocd.poll() is None:
                attempt('owned_openocd_shutdown', lambda: self.tcl.call('shutdown'))
            attempt('owned_tcl_socket', self.tcl.close)
        if self.ocd is not None:
            def close_ocd():
                if self.ocd.poll() is None:
                    try: self.ocd.wait(3)
                    except subprocess.TimeoutExpired:
                        self.ocd.terminate()
                        try: self.ocd.wait(3)
                        except subprocess.TimeoutExpired: self.ocd.kill(); self.ocd.wait(3)
            attempt('owned_openocd_process', close_ocd)
        if self.ocd_log is not None:
            attempt('owned_openocd_log', self.ocd_log.close)
        if self.com is not None:
            attempt('owned_serial', self.com.close)
        return errors


OWNED = OwnedSession()


def prepare(argv=None):
    global PKGENV, D, EXPECTED, EXPECTED_SHA, IMG_N, BUILD_B
    parser = argparse.ArgumentParser(description='Portable LT3 game loader; programs RAM and resets the CPU')
    parser.add_argument('package', type=Path); parser.add_argument('log_dir', type=Path)
    parser.add_argument('--prepare-only', '--check-only', action='store_true', dest='prepare_only',
                        help='Verify package/layout and create expected RAM image without any device access')
    args = parser.parse_args(argv)
    PKGENV = pkg_env.load(args.package); s3.configure(PKGENV['pkg'])
    D = args.log_dir.resolve(); D.mkdir(parents=True, exist_ok=True)
    for name in ('load_session_result.json', 'gdb_transcript.log', 'openocd.log', 'com15_rx.bin'):
        if (D / name).exists(): raise RuntimeError('Refusing to overwrite prior loader evidence: ' + str(D / name))
    s3.ELF = PKGENV['elf']; s3.ELF_SHA = PKGENV['elf_sha256']
    EXPECTED = pkg_env.expected_image(PKGENV, D); EXPECTED_SHA = hashlib.sha256(EXPECTED.read_bytes()).hexdigest()
    IMG_N = EXPECTED.stat().st_size; BUILD_B = PKGENV['build_id'].encode()
    return args.prepare_only


def log(k, v):
    R['steps'].append({'t': datetime.datetime.now().isoformat(timespec='milliseconds'), k: v}); print(k, v, flush=True)


class Com:
    """COM15 reader thread (everything received is kept with time stamps); writes only the ASSET BUILD query."""
    def __init__(self):
        import serial
        self.s = self.raw = self.th = None; self.run = False; self.closed = False; self.error = None; self.buf = bytearray()
        OWNED.com = self
        self.raw = open(D / 'com15_rx.bin', 'wb')
        self.s = serial.Serial(s3.PORT, 115200, timeout=0.05, write_timeout=3)
        self.run = True; self.th = threading.Thread(target=self._rd, daemon=True); self.th.start()
    def _rd(self):
        try:
            while self.run:
                b = self.s.read(4096)
                if b: self.buf.extend(b); self.raw.write(b); self.raw.flush()
        except Exception as exc:
            if self.run: self.error = repr(exc)
    def wait(self, needle, t):
        e = time.time() + t
        while time.time() < e:
            if self.error: raise RuntimeError('UART reader failed: ' + self.error)
            if needle in self.buf: return True
            time.sleep(0.02)
        return needle in self.buf
    def query_build(self):
        if self.error: raise RuntimeError('UART reader failed: ' + self.error)
        n0 = len(self.buf); self.s.write(b'ASSET BUILD\r\n'); e = time.time() + 3
        while time.time() < e:
            if self.error: raise RuntimeError('UART reader failed: ' + self.error)
            i = self.buf.find(b'ASSET BUILD ', n0)
            if i >= 0 and b'\n' in self.buf[i:]: return self.buf[i:self.buf.index(b'\n', i)].decode(errors='replace').strip()
            time.sleep(0.02)
        return None
    def close(self):
        if self.closed: return
        self.closed = True; self.run = False
        errors = []
        if self.s is not None:
            try:
                if hasattr(self.s, 'cancel_read'): self.s.cancel_read()
            except Exception as exc: errors.append(repr(exc))
            try: self.s.close()
            except Exception as exc: errors.append(repr(exc))
        if self.th is not None:
            self.th.join(2)
            if self.th.is_alive(): errors.append('UART reader thread did not exit within 2 seconds')
        if self.raw is not None:
            try: self.raw.close()
            except Exception as exc: errors.append(repr(exc))
        if errors: raise RuntimeError('; '.join(errors))


class Gdb:
    def __init__(self):
        self.p = self.tr = self.th = None; self.closed = False; self.error = None; self.buf = bytearray(); self.n = 0
        OWNED.gdb = self
        self.tr = open(D / 'gdb_transcript.log', 'wb')
        self.p = subprocess.Popen([TC + 'gdb.exe', '-q', '-nx'], cwd=D, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                  creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        self.th = threading.Thread(target=self._rd, daemon=True); self.th.start()
    def _rd(self):
        try:
            while True:
                b = self.p.stdout.read1(4096)
                if not b: break
                self.buf.extend(b); self.tr.write(b); self.tr.flush()
        except Exception as exc:
            if not self.closed: self.error = repr(exc)
    def cmd(self, c, t=60):
        self.n += 1; m = b'@@DONE%d@@' % self.n; start = len(self.buf)
        self.tr.write(b'\n>>> ' + c.encode() + b'\n')
        self.p.stdin.write(c.encode() + b'\n' + b'echo @@DONE%d@@' % self.n + b'\\n\n'); self.p.stdin.flush(); e = time.time() + t
        while m not in self.buf[start:] and time.time() < e:
            if self.error: raise RuntimeError('GDB reader failed: ' + self.error)
            if self.p.poll() is not None: break
            time.sleep(0.02)
        out = self.buf[start:].decode(errors='replace'); done = m in self.buf[start:]
        return out.split('@@DONE')[0] if done else out, done
    def close(self):
        if self.closed: return
        self.closed = True
        try:
            if self.p is not None and self.p.poll() is None:
                try:
                    self.p.stdin.write(b'set confirm off\ndisconnect\nquit\n'); self.p.stdin.flush()
                    self.p.wait(3)
                except Exception:
                    if self.p.poll() is None:
                        self.p.terminate()
                        try: self.p.wait(3)
                        except subprocess.TimeoutExpired: self.p.kill(); self.p.wait(3)
        finally:
            if self.th is not None: self.th.join(2)
            if self.p is not None:
                for stream in (self.p.stdin, self.p.stdout):
                    try:
                        if stream is not None: stream.close()
                    except Exception: pass
            if self.tr is not None: self.tr.close()


def parse_words(o):
    """words of an 'x/Nwx' reply: per line, only the values after the 'address <sym>:' label"""
    w = []
    for line in o.splitlines():
        if ':' in line and '0x' in line.split(':', 1)[0]:
            w += [int(x, 16) for x in re.findall(r'0x([0-9a-f]+)', line.split(':', 1)[1])]
    return w


def elf_facts():
    run = lambda *a: subprocess.run([TC + a[0] + '.exe', *a[1:]], capture_output=True, text=True, check=True).stdout
    nm = run('nm', '-S', str(s3.ELF)); f = {}
    for l in nm.splitlines():
        p = l.split()
        if len(p) == 4 and p[3] == 'main': f['main'] = int(p[0], 16); f['main_size'] = int(p[1], 16)
        if len(p) >= 3 and p[-1] in ('_sp', '__global_pointer$'): f[p[-1]] = int(p[0], 16)
    first = run('objdump', '-d', '--no-show-raw-insn', f'--start-address={f["main"]:#x}', f'--stop-address={f["main"] + 4:#x}', str(s3.ELF))
    f['main_frame'] = -int(re.search(r'addi\s+sp,sp,(-\d+)', first).group(1))
    return f, run


def main():
    # ---- gates (no device access)
    a2 = (D / 'step2_program_bit.log').read_text(encoding='utf-8', errors='replace'); st = (D / 'step2b_status.log').read_text(encoding='utf-8', errors='replace')
    gate = {'bit_sha_logged': ('BIT_SHA256 ' + PKGENV['bit_sha256']) in a2, 'idcode': 'Device ID read from JTAG: 0x10660A79' in a2,
            'programmed': 'finished with JTAG programming' in a2 and 'STEP2_EXIT=0' in a2, 'user_mode': 'PROG_STATE=USER_MODE' in st and 'STEP2B_EXIT=0' in st,
            'elf_sha': hashlib.sha256(s3.ELF.read_bytes()).hexdigest() == s3.ELF_SHA, 'expected_image_sha': hashlib.sha256(EXPECTED.read_bytes()).hexdigest() == EXPECTED_SHA,
            'no_openocd_gdb': not any(x in subprocess.run(['tasklist'], capture_output=True, text=True).stdout for x in ('openocd.exe', 'riscv-none-elf-gdb.exe'))}
    log('gate', gate)
    if not all(gate.values()): return finish(False, 'gate failed: nothing started')
    F, run = elf_facts(); log('elf_facts', {k: hex(v) for k, v in F.items()})
    com = Com()
    s3.assert_debug_ports_free()
    OWNED.ocd_log = open(D / 'openocd.log', 'wb')
    ocd = subprocess.Popen([str(s3.OCD)] + s3.OCD_ARGS, cwd=s3.APB, stdout=OWNED.ocd_log, stderr=subprocess.STDOUT,
                          creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
    OWNED.ocd = ocd
    log('openocd_cmd', [str(s3.OCD)] + s3.OCD_ARGS); log('openocd_cwd', str(s3.APB))
    e = time.time() + 40
    while time.time() < e and 'Listening on port 6666' not in (D / 'openocd.log').read_text(errors='replace') and ocd.poll() is None: time.sleep(0.2)
    if 'Listening on port 6666' not in (D / 'openocd.log').read_text(errors='replace'):
        return finish(False, 'OpenOCD did not start')
    tcl = s3.Tcl(); OWNED.tcl = tcl; g = Gdb()

    def stop_halted(why):
        log('failure', why)
        if tcl.call('fpga_spinal.cpu0 curstate').strip() != 'halted': log('halt', tcl.call('halt'))
        log('pc_at_failure', tcl.call('reg pc').strip())
        return finish(False, why + ' (CPU left halted, not retried)')

    for c in ('set pagination off', 'set confirm off', 'set mem inaccessible-by-default off', 'set arch riscv:rv32', 'set remotetimeout 250',
              'file "' + s3.ELF.as_posix() + '"'):
        g.cmd(c, 20)
    o, ok = g.cmd('target remote localhost:3333', 30); log('target_remote', o.strip()[-200:])
    if not ok or 'Remote debugging using' not in o: return stop_halted('GDB could not connect')
    o, ok = g.cmd('monitor reset init', 30); log('reset_init', o.strip()[-200:])
    o, ok = g.cmd('load', 120); log('load', o.strip())
    if not ok or f'Start address 0xf9000000, load size {IMG_N}' not in o or 'Transfer rate' not in o: return stop_halted('load not confirmed')
    o, ok = g.cmd('monitor reset halt', 30); log('reset_halt', o.strip()[-200:])
    o, ok = g.cmd('printf "PC_RESET=0x%08x\\n", $pc', 10); log('pc_after_reset_halt', o.strip())
    if 'PC_RESET=0xf9000000' not in o: return stop_halted('pc after reset halt is not the entry 0xf9000000')
    dump = D / 'ram_after_load.bin'
    o, ok = g.cmd(f'dump binary memory ram_after_load.bin 0xf9000000 {0xf9000000 + IMG_N:#x}', 180)
    got = dump.read_bytes() if dump.exists() else b''; img = got == EXPECTED.read_bytes()
    log('image_readback', {'bytes': len(got), 'equal': img, 'sha256': hashlib.sha256(got).hexdigest()})
    if not img: return stop_halted('RAM image differs from the ELF')
    # GHD6 LT2: read-only RAM-configuration fingerprint. The full 1 KiB [bootloader_start, ram_end) is read back and logged; the check
    # passes only if the immutable bootloader_144K code range equals the package's expected bytes (a 160 KiB bit reads zeros there).
    rb, re_ = int(PKGENV['ram']['bootloader_start'], 16), int(PKGENV['ram']['end'], 16); bdump = D / 'ram_bootloader_region.bin'
    o, ok = g.cmd(f'dump binary memory ram_bootloader_region.bin {rb:#x} {re_:#x}', 60)
    bgot = bdump.read_bytes() if bdump.exists() else b''; fp = pkg_env.fingerprint(PKGENV, bgot)
    (D / 'ram_bootloader_region_diff.json').write_text(json.dumps(fp, indent=1) + '\n')
    log('ram144_fingerprint', {'region': [hex(rb), hex(re_)], 'sha256': hashlib.sha256(bgot).hexdigest(), 'ram_gate': PKGENV['ram_gate'],
                               **{k: fp[k] for k in ('ok', 'code_range', 'code_equal', 'full_region_equal', 'bytes', 'differing_words', 'differing_words_in_code')}})
    if not fp['ok']: return stop_halted('RAM configuration fingerprint mismatch: the bootloader_144K code range differs (the programmed bit is not the 144 KiB layout of this package)')
    o, ok = g.cmd('tbreak main', 10); log('tbreak', o.strip()); m = re.search(r'Temporary breakpoint \d+ at 0x([0-9a-f]+)', o)
    if not m: return stop_halted('GDB did not resolve the main breakpoint')
    bp = int(m.group(1), 16)
    o, ok = g.cmd('continue', 30); log('continue', o.strip())
    if not ok: return stop_halted('main not reached within 30 s')
    regs = 'printf "STOP pc=0x%08x sp=0x%08x gp=0x%08x ra=0x%08x\\n", $pc, $sp, $gp, $ra'
    o1, _ = g.cmd(regs, 10); r1 = {k: int(v, 16) for k, v in re.findall(r'(pc|sp|gp|ra)=0x([0-9a-f]+)', o1)}; log('stop_regs_1', {k: hex(v) for k, v in r1.items()})
    ocd_pc1 = tcl.call('reg pc').strip(); log('openocd_reg_pc_1', ocd_pc1)
    state = tcl.call('fpga_spinal.cpu0 curstate').strip(); log('openocd_state', state)
    o, _ = g.cmd('x/6wx $pc', 10); words = parse_words(o)
    log('words_at_pc', o.strip())
    o_dis, _ = g.cmd('x/6i $pc', 10); log('disasm_at_pc_gdb', o_dis.strip())
    pc = r1.get('pc', -1)
    ref = run('objdump', '-d', '--no-show-raw-insn', f'--start-address={pc:#x}', f'--stop-address={pc + 24:#x}', str(s3.ELF))
    log('disasm_at_pc_elf', ref.strip()[-600:])
    img_b = EXPECTED.read_bytes(); off = pc - 0xf9000000
    elf_words = [int.from_bytes(img_b[off + 4 * i:off + 4 * i + 4], 'little') for i in range(6)] if 0 <= off <= len(img_b) - 24 else None
    log('elf_words_at_pc', [hex(x) for x in elf_words] if elf_words else None)
    time.sleep(2.0)
    o2, _ = g.cmd(regs, 10); r2 = {k: int(v, 16) for k, v in re.findall(r'(pc|sp|gp|ra)=0x([0-9a-f]+)', o2)}; log('stop_regs_2', {k: hex(v) for k, v in r2.items()})
    ocd_pc2 = tcl.call('reg pc').strip(); log('openocd_reg_pc_2', ocd_pc2)
    checks = {
        'gdb_breakpoint_is_stop_pc': pc == bp,
        'pc_inside_main': F['main'] <= pc < F['main'] + F['main_size'],
        'code_at_pc_equals_elf': elf_words is not None and words[:6] == elf_words,
        'sp_is_sp_minus_main_frame': r1.get('sp') == F['_sp'] - F['main_frame'],
        'gp_is_global_pointer': r1.get('gp') == F['__global_pointer$'],
        'state_halted': state == 'halted',
        'pc_stable_gdb': r1 == r2,
        'pc_stable_openocd': ocd_pc1 == ocd_pc2 and f'0x{pc:08x}' in ocd_pc1.lower(),
    }
    log('startup_checks', checks)
    if not all(checks.values()):
        why = 'pc changed while halted in the same session' if not (checks['pc_stable_gdb'] and checks['pc_stable_openocd']) else 'start-up state check failed'
        return stop_halted(why)
    # ---- Resume in the same session (current pc, nothing written)
    o, _ = g.cmd('monitor resume', 10); log('resume', o.strip())
    R['firmware_resume_requested'] = True
    time.sleep(0.3); run_state = tcl.call('fpga_spinal.cpu0 curstate').strip(); log('state_after_resume', run_state)
    banner = com.wait(b'BUILD: ' + BUILD_B, 5); log('banner_seen', banner)
    rep1 = com.query_build(); log('asset_build_session_open', rep1)
    o, _ = g.cmd('disconnect', 10); log('gdb_disconnect', o.strip()); g.cmd('quit', 5)
    try: g.p.wait(10)
    except subprocess.TimeoutExpired: g.p.kill()
    time.sleep(0.5); st_disc = tcl.call('fpga_spinal.cpu0 curstate').strip(); log('state_after_gdb_disconnect', st_disc)
    log('openocd_shutdown', tcl.call('shutdown'))
    try: ocd.wait(30)
    except subprocess.TimeoutExpired: ocd.kill(); log('openocd_killed', True)
    log('openocd_rc', ocd.returncode)
    time.sleep(1.5); rep2 = com.query_build(); log('asset_build_after_openocd_exit', rep2)
    nb = bytes(com.buf).count(b'BUILD: ' + BUILD_B); log('banner_count', nb)
    com.close()
    # LT3: identity expectation from the verified package record (pkg_env.load), never from the board reply
    id1, id2 = pkg_env.identity_ok(PKGENV, rep1), pkg_env.identity_ok(PKGENV, rep2); log('identity_check', {'while_attached': id1[1], 'after_openocd_exit': id2[1]})
    final = {'running_after_resume': run_state == 'running', 'banner': banner, 'asset_build_while_attached': id1[0],
             'running_after_gdb_disconnect': st_disc == 'running', 'asset_build_after_openocd_exit': id2[0], 'single_banner_no_reset': nb == 1}
    log('final_checks', final)
    return finish(all(final.values()), '' if all(final.values()) else 'post-resume confirmation incomplete')


def finish(ok, why):
    R['pass'] = ok; R['stop_reason'] = why; R['end'] = datetime.datetime.now().isoformat(timespec='seconds')
    (D / 'load_session_result.json').write_text(json.dumps(R, indent=1, default=str) + '\n', encoding='utf-8')
    print('LOAD_SESSION', 'PASS' if ok else 'FAIL', why); return 0 if ok else 1


def run(argv=None):
    result = 1
    try:
        if prepare(argv):
            R.update(verification_stage='static_only', device_operation=False, pass_static=True)
            print('LOAD_PREPARE_ONLY PASS', PKGENV['build_id'], PKGENV['sums_verified'], 'files; no device access', flush=True)
            result = 0
        else:
            R.update(verification_stage='board_load', device_operation=True)
            result = main()
    except BaseException as exc:
        if isinstance(exc, SystemExit) and not D:
            raise
        R['pass'] = False; R['stop_reason'] = f'{type(exc).__name__}: {exc}'
        R['exception_traceback'] = traceback.format_exc()
        # Before the verified Resume phase an incomplete image must not execute.
        # Only this session's target connection is used; no new server is attached.
        if OWNED.tcl is not None and OWNED.ocd is not None and OWNED.ocd.poll() is None and not R.get('firmware_resume_requested'):
            try: log('halt_after_unexpected_load_exception', OWNED.tcl.call('halt'))
            except Exception as halt_error: R['exception_halt_error'] = repr(halt_error)
        print('LOAD_SESSION FAIL', R['stop_reason'], flush=True)
    finally:
        R['cleanup_errors'] = OWNED.cleanup()
        if R['cleanup_errors']: result = 1; R['pass'] = False
        R['end'] = datetime.datetime.now().isoformat(timespec='seconds')
        if D is not None:
            (D / 'load_session_result.json').write_text(json.dumps(R, indent=1, default=str) + '\n', encoding='utf-8')
    return result


if __name__ == '__main__':
    sys.exit(run())
